function computeWaterLegacy449(){
  let towers=0,desalRoots=0;
  for(let i=0;i<N*N;i++){
    const b=tiles[i].bld;tiles[i].wr=false;
    if(b&&!b.ref){if(b.k===10)towers++;else if(b.k===129)desalRoots++;}
  }
  if(!towers&&!desalRoots)return 0;
  const seen=new Uint8Array(N*N);
  const q=[];
  for(let y=0;y<N;y++)for(let x=0;x<N;x++){
    const t=T(idx(x,y));
    if(!(t.bld&&(t.bld.k===10||t.bld.k===129)))continue; // T364d：2×2 淡化廠每一側均可接水管，但容量只在 root 計一次
    for(const[dx,dy]of[[0,-1],[1,0],[0,1],[-1,0]]){
      const nx=x+dx,ny=y+dy;
      if(inMap(nx,ny)&&T(idx(nx,ny)).wp&&!seen[idx(nx,ny)]){
        seen[idx(nx,ny)]=1;q.push([nx,ny,0]);
      }
    }
  }
  let head=0;
  while(head<q.length){
    const[x,y,d]=q[head++];
    T(idx(x,y)).wr=true;
    if(d>=90)continue;
    for(const[dx,dy]of[[0,-1],[1,0],[0,1],[-1,0]]){
      const nx=x+dx,ny=y+dy;
      if(!inMap(nx,ny))continue;
      const j=idx(nx,ny);
      if(T(j).wp&&!seen[j]){seen[j]=1;q.push([nx,ny,d+1]);}
    }
  }
  return towers*WATER_TOWER_CAP+desalRoots*DESAL_CAP;
}

